(() => {
const api=async(path,options={})=>{const res=await fetch(StayCorePMS.root+path,{cache:'no-store',...options,headers:{'Content-Type':'application/json','X-WP-Nonce':StayCorePMS.nonce,...(options.headers||{})}});const data=await res.json();if(!res.ok){const err=new Error(data.message||'Request failed');err.code=data.code||'request_failed';err.data=data.data||{};throw err}return data};
const el=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=v=>String(v||'').slice(0,10), money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:2}), digits=v=>String(v||'').replace(/\D/g,'');
const waWebUrl=(phone,text='')=>{const p=digits(phone),q=text?'?text='+encodeURIComponent(text):'';return 'https://wa.me/'+p+q};
const waBusinessUrl=(phone,text='')=>{const web=waWebUrl(phone,text);if(!/Android/i.test(navigator.userAgent))return web;const query='phone='+digits(phone)+(text?'&text='+encodeURIComponent(text):'');return 'intent://send?'+query+'#Intent;scheme=whatsapp;package=com.whatsapp.w4b;S.browser_fallback_url='+encodeURIComponent(web)+';end'};
const routeWhatsApp=(phone,text='',targetWin=null)=>{const url=waBusinessUrl(phone,text);if(targetWin){targetWin.location.href=url;return url}window.open(url,'_blank','noopener');return url};
const pretty=v=>{if(!v)return'';const d=new Date(String(v).replace(' ','T'));return isNaN(d)?String(v).slice(0,16):d.toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})};
const addDays=(s,n)=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const state={tab:StayCorePMS.initial_view==='attention'?'attention':'rooms',date:StayCorePMS.today,roomFilter:'all',bookingFilter:'today',search:'',units:[],dashboard:null,more:'home'};
const applyCardSearch=(input,containerSelector,cardSelector,countSelector)=>{const q=String(input.value||'').trim().toLowerCase();state.search=input.value;const cards=[...document.querySelectorAll(containerSelector+' '+cardSelector)];let visible=0;cards.forEach(card=>{const match=!q||String(card.dataset.search||card.textContent||'').toLowerCase().includes(q);card.hidden=!match;if(match)visible++});const empty=document.querySelector(containerSelector+' .sc-search-empty');if(empty)empty.hidden=visible!==0;const count=countSelector?document.querySelector(countSelector):null;if(count)count.textContent=String(visible)};

let scOcrPromise=null;
const loadOCR=()=>scOcrPromise||(scOcrPromise=new Promise((resolve,reject)=>{if(window.Tesseract){resolve(window.Tesseract);return}const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';s.async=true;s.onload=()=>resolve(window.Tesseract);s.onerror=()=>reject(new Error('Could not load the scanner. Check internet and try again.'));document.head.appendChild(s)}));
const scanText=async(file,statusEl)=>{const T=await loadOCR();const r=await T.recognize(file,'eng',{logger:m=>{if(statusEl&&m.status==='recognizing text')statusEl.textContent='Reading image… '+Math.round((m.progress||0)*100)+'%'}});return String(r?.data?.text||'')};
const parseDateValue=s=>{if(!s)return'';const v=String(s).replace(/[,]/g,' ').replace(/\s+/g,' ').trim(),m=v.match(/(\d{1,2})[\s\/-](Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?|\d{1,2})[\s\/-](\d{2,4})/i);if(!m)return'';const months={jan:1,january:1,feb:2,february:2,mar:3,march:3,apr:4,april:4,may:5,jun:6,june:6,jul:7,july:7,aug:8,august:8,sep:9,september:9,oct:10,october:10,nov:11,november:11,dec:12,december:12};let mo=/^\d+$/.test(m[2])?Number(m[2]):months[m[2].toLowerCase()],y=Number(m[3]);if(y<100)y+=2000;if(!mo||mo>12)return'';return y+'-'+String(mo).padStart(2,'0')+'-'+String(Number(m[1])).padStart(2,'0')};
const fillBookingFromText=(text,form)=>{const t=String(text||'').replace(/\r/g,''),set=(name,val)=>{if(val&&form.elements[name]){form.elements[name].value=val;form.elements[name].dispatchEvent(new Event('input',{bubbles:true}))}},line=(re)=>{const m=t.match(re);return m?m[1].trim():''};
const email=(t.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)||[])[0]||'',phoneRaw=(t.match(/(?:\+?\d[\d\s()-]{8,}\d)/)||[])[0]||'',phone=phoneRaw.replace(/[^\d+]/g,'');
let source='';if(/goibibo/i.test(t))source='goibibo';else if(/make\s*my\s*trip|makemytrip/i.test(t))source='makemytrip';else if(/booking\.com|booking com/i.test(t))source='booking';else if(/airbnb/i.test(t))source='airbnb';else if(/agoda/i.test(t))source='agoda';
const guest=line(/(?:guest(?:\s+name)?|primary\s+guest|lead\s+guest)\s*[:\-]?\s*([^\n]{2,80})/i),parts=guest.split(/\s+/).filter(Boolean);if(parts.length){set('first_name',parts.shift());set('last_name',parts.join(' '))}
set('email',email);set('phone',phone);if(source)set('source',source);
set('external_ref',line(/(?:booking(?:\s+id|\s+reference|\s+ref)?|confirmation(?:\s+number)?|reservation(?:\s+id)?)\s*[:#\-]?\s*([A-Z0-9\-]{4,})/i));
const total=line(/(?:total(?:\s+amount)?|amount\s+paid|booking\s+amount)\s*[:₹INR ]+([\d,]+(?:\.\d{1,2})?)/i).replace(/,/g,'');set('total',total);
const ci=line(/check[\s-]*in\s*[:\-]?\s*([^\n]{4,40})/i),co=line(/check[\s-]*out\s*[:\-]?\s*([^\n]{4,40})/i),cid=parseDateValue(ci),cod=parseDateValue(co);
if(cid&&form.elements.check_in)form.elements.check_in.value=cid+'T'+String(form.elements.check_in.value||'13:00').slice(11,16);
if(cod&&form.elements.check_out)form.elements.check_out.value=cod+'T'+String(form.elements.check_out.value||'11:00').slice(11,16);
return [guest&&'guest',phone&&'phone',email&&'email',source&&'source',cid&&'check-in',cod&&'check-out',total&&'total'].filter(Boolean)};

const assignedNames=r=>(r.assignments||[]).map(a=>a.name).join(', ');
const payBadge=r=>{const p=r.payment||{};return '<span class="sc-pay '+esc(p.status||'not_set')+'">'+esc((p.status||'not set').replace('_',' '))+'</span>'};
const statusBadge=r=>'<span class="sc-badge '+esc(r.status)+'">'+esc(String(r.status||'').replace('_',' '))+'</span>';

const roomNumber=u=>{const m=String(u.name||u.room_group||'').match(/Room\s+(\d+)/i);return m?Number(m[1]):9999};
const roomKey=u=>u.type==='room'?u.name:'Room '+roomNumber(u);
const roomType=units=>{const f=units[0]||{};if(f.type==='room')return f.room_group||'Private Room';const m=String(f.room_group||'').split('—');return(m[1]||f.room_group||'Dorm').trim()};
const groupRooms=units=>{const map={};units.forEach(u=>{const k=roomKey(u);if(!map[k])map[k]={key:k,number:roomNumber(u),units:[]};map[k].units.push(u)});return Object.values(map).sort((a,b)=>a.number-b.number).map(g=>{g.units.sort((a,b)=>String(a.name).localeCompare(String(b.name),undefined,{numeric:true}));g.type=roomType(g.units);g.private=g.units.length===1&&g.units[0].type==='room';g.capacity=g.private?Number(g.units[0].capacity||1):g.units.length;return g})};
const activeOn=(r,d)=>day(r.check_in)<=d&&day(r.check_out)>=d&&!['cancelled','no_show','checked_out'].includes(r.status)&&!(day(r.check_out)===d&&String(r.check_out).slice(11,16)<='11:00');
const resForUnit=(rows,uid,d)=>rows.find(r=>activeOn(r,d)&&(r.assignments||[]).some(a=>Number(a.unit_id)===Number(uid)));
const firstName=r=>String(r.guest_name||'Guest').trim().split(/\s+/)[0];

const attentionBreakdownText=b=>{const labels={payment:'payment',overdue:'overdue',service_recovery:'guest issue',contact:'missing contact'};return Object.entries(b||{}).filter(([,n])=>Number(n)>0).map(([k,n])=>Number(n)+' '+(labels[k]||k)).join(' · ')};
const loadDashboard=async()=>{state.dashboard=await api('dashboard');const d=state.dashboard;
const items=StayCorePMS.caps.reservations?[
  ['arrivals','Arrivals',d.arrival_units??d.arrivals],
  ['departures','Departures',d.departure_units??d.departures],
  ['inhouse','In house',d.inhouse_units??d.inhouse],
  ['available','Ready',d.available_units],
  ['cleaning','Cleaning',d.cleaning_units||0]
]:[
  ['cleaning','To clean',d.cleaning_units||0],
  ['available','Ready',d.available_units],
  ['inhouse','Occupied',(d.inhouse_units??d.occupied_units??0)],
  ['maintenance','Maintenance',d.maintenance_units||0]
];
el('#sc-kpis').innerHTML=items.map(([k,l,v])=>'<button class="sc-kpi" data-kpi="'+k+'"><strong>'+v+'</strong><span>'+l+'</span></button>').join('');
document.querySelectorAll('[data-kpi]').forEach(b=>b.onclick=()=>{state.search='';state.date=StayCorePMS.today;state.tab='rooms';state.roomFilter=b.dataset.kpi;activateTab('rooms');renderRooms()});
const attentionCount=Number(d.attention_count??(d.alerts||[]).length),breakdown=attentionBreakdownText(d.attention_breakdown);
el('#sc-alerts').innerHTML=attentionCount?'<div class="sc-attention-summary"><button class="sc-attention-open" id="sc-show-alerts"><strong>'+attentionCount+'</strong><span>'+ (attentionCount===1?'booking needs attention':'bookings need attention') +'</span></button>'+(breakdown?'<div class="sc-attention-breakdown">'+esc(breakdown)+'</div>':'')+'</div>':'';
if(el('#sc-show-alerts'))el('#sc-show-alerts').onclick=()=>{if(StayCorePMS.attention_url){window.location.href=StayCorePMS.attention_url;return}state.tab='attention';activateTab('attention');renderAttention()};
};

const bindOpen=()=>document.querySelectorAll('.sc-open').forEach(b=>b.onclick=()=>openReservation(b.dataset.id).catch(e=>alert(e.message)));
const checkoutMessage=r=>'Thanks for staying at Andaz Vibe Stay. We would love to know how your stay was. It takes less than a minute:\n\n'+r.feedback_url;
const showCheckoutSuccess=r=>{const d=el('#sc-dialog'),msg=checkoutMessage(r);d.innerHTML='<div class="sc-success"><div class="sc-success-icon">✓</div><h2>Checkout complete</h2><div class="sc-meta">'+esc((r.guest_name||'Guest').trim())+' · room/bed moved to housekeeping</div><div class="sc-success-actions">'+(r.phone?'<a class="button button-primary" target="_blank" rel="noopener" href="'+waBusinessUrl(r.phone,msg)+'">Send via WhatsApp Business</a>':'<button class="button" disabled>No guest phone available</button>')+'<button class="button sc-copy-feedback" type="button">Copy feedback link</button><button class="button sc-open-success" type="button">Open booking</button><button class="button sc-done-success" type="button">Done</button></div><div class="sc-meta sc-success-note">Manual send for now · automation can use the same link later.</div></div>';if(!d.open)d.showModal();d.querySelector('.sc-copy-feedback').onclick=async()=>{try{await navigator.clipboard.writeText(r.feedback_url);d.querySelector('.sc-copy-feedback').textContent='Copied'}catch(e){window.prompt('Copy feedback link',r.feedback_url)}};d.querySelector('.sc-open-success').onclick=()=>openReservation(r.id);d.querySelector('.sc-done-success').onclick=()=>d.close()};
const setStatus=async(id,status)=>{if(status==='checked_out'&&!window.confirm('Check out this guest? Their assigned room/bed will move to Needs cleaning.'))return;const waWin=status==='checked_out'?window.open('about:blank','_blank'):null;try{const r=await api('reservations/'+id+'/status',{method:'POST',body:JSON.stringify({status})});await refresh();if(status==='checked_out'){if(waWin){if(r.phone)routeWhatsApp(r.phone,checkoutMessage(r),waWin);else waWin.close()}showCheckoutSuccess(r)}}catch(e){if(waWin)waWin.close();if(status==='checked_out'&&e.code==='payment_due'){await openReservation(id,true,Number(e.data?.balance||0));return}throw e}};
const bindStatus=()=>{document.querySelectorAll('.sc-status').forEach(b=>b.onclick=()=>setStatus(b.dataset.id,b.dataset.status).catch(e=>alert(e.message)));document.querySelectorAll('.sc-payment-needed').forEach(b=>b.onclick=()=>openReservation(b.dataset.id,true).catch(e=>alert(e.message)))};
const checkoutAction=r=>{if(r.status!=='checked_in'||!StayCorePMS.caps.checkout)return'';const due=Number(r.payment?.balance||0);return due>0.009?'<button class="button button-primary sc-payment-needed" data-id="'+r.id+'">Collect payment</button>':'<button class="button button-primary sc-status" data-id="'+r.id+'" data-status="checked_out">Check out</button>'};

const compactGuest=r=>StayCorePMS.caps.reservations?'<div class="sc-guest-line"><div class="sc-row"><button class="sc-link sc-open" data-id="'+r.id+'">'+esc((r.guest_name||'Guest').trim())+'</button>'+statusBadge(r)+'</div><div class="sc-meta">'+pretty(r.check_out)+' checkout · '+esc(r.source||'direct')+'</div><div class="sc-row" style="margin-top:7px">'+(StayCorePMS.caps.payments?payBadge(r):'')+'<button class="button sc-open" data-id="'+r.id+'">Open</button></div></div>':'<div class="sc-guest-line"><div class="sc-row"><strong>'+esc((r.guest_name||'Guest').trim())+'</strong>'+statusBadge(r)+'</div><div class="sc-meta">Occupied until '+pretty(r.check_out)+'</div></div>';

const setHousekeeping=async(unitIds,status)=>{await api('housekeeping',{method:'POST',body:JSON.stringify({unit_ids:unitIds,status})});await loadDashboard();await renderRooms()};
const reservationsForUnit=(rows,uid)=>rows.filter(r=>(r.assignments||[]).some(a=>Number(a.unit_id)===Number(uid)));
const filterReservationForUnit=(rows,u,filter,date)=>{const rs=reservationsForUnit(rows,u.id);
if(filter==='arrivals')return rs.find(r=>day(r.check_in)===date&&r.status==='confirmed')||null;
if(filter==='departures')return rs.find(r=>day(r.check_out)===date&&r.status==='checked_in')||null;
if(filter==='inhouse')return rs.find(r=>r.status==='checked_in')||null;
return resForUnit(rows,u.id,date)||null};
const unitMatchesRoomFilter=(u,rows,filter,date)=>{
const filterRes=filterReservationForUnit(rows,u,filter,date),reserved=reservationsForUnit(rows,u.id).some(r=>['confirmed','checked_in'].includes(r.status));
if(filter==='all')return true;
if(['arrivals','departures','inhouse'].includes(filter))return !!filterRes;
if(filter==='available')return !reserved&&u.status==='available'&&(u.housekeeping_status||'clean')==='clean';
if(filter==='cleaning')return !reserved&&u.status==='available'&&['dirty','cleaning'].includes(u.housekeeping_status||'clean');
if(filter==='maintenance')return (u.housekeeping_status||'clean')==='maintenance';
return true;
};
const renderRooms=async()=>{state.units=await api('units');const rows=await api('reservations?from='+state.date+'&to='+state.date),rooms=groupRooms(state.units),cards=[];let visibleUnitCount=0;
for(const g of rooms){
  const fullReservations=[];g.units.forEach(u=>{const rr=resForUnit(rows,u.id,state.date);if(rr&&!fullReservations.some(x=>x.id===rr.id))fullReservations.push(rr)});
  const matched=g.units.filter(u=>unitMatchesRoomFilter(u,rows,state.roomFilter,state.date));
  if(!matched.length)continue;
  const filtered=state.roomFilter!=='all',visibleUnits=filtered?matched:g.units;visibleUnitCount+=visibleUnits.length;
  const visibleReservations=[];visibleUnits.forEach(u=>{const rr=state.roomFilter==='all'?resForUnit(rows,u.id,state.date):filterReservationForUnit(rows,u,state.roomFilter,state.date);if(rr&&!visibleReservations.some(x=>x.id===rr.id))visibleReservations.push(rr)});
  const hay=(g.key+' '+g.type+' '+visibleUnits.map(u=>u.name).join(' ')+' '+visibleReservations.map(r=>(r.guest_name||'')+' '+(r.phone||'')+' '+assignedNames(r)).join(' ')).toLowerCase();
  const turnoverUnit=u=>{const label=u.type==='room'?u.name:String(u.name).split('·').pop().trim(),s=u.housekeeping_status;
    if(s==='dirty')return '<button class="sc-bed dirty sc-hk-action" data-unit="'+u.id+'" data-hk="cleaning"><strong>'+esc(label)+'</strong><span>Vacant · not ready</span><span>Needs cleaning</span></button>';
    if(s==='cleaning')return '<button class="sc-bed cleaning sc-hk-action" data-unit="'+u.id+'" data-hk="clean"><strong>'+esc(label)+'</strong><span>Vacant · not ready</span><span>Cleaning</span></button>';
    if(s==='maintenance')return '<div class="sc-bed maintenance"><strong>'+esc(label)+'</strong><span>Maintenance</span></div>';
    return '<div class="sc-bed free"><strong>'+esc(label)+'</strong><span>Ready</span></div>'};
  const unitTile=u=>{const rr=filtered?filterReservationForUnit(rows,u,state.roomFilter,state.date):resForUnit(rows,u.id,state.date),label=u.type==='room'?u.name:String(u.name).split('·').pop().trim();
    if(rr)return StayCorePMS.caps.reservations?'<button class="sc-bed occupied sc-open" data-id="'+rr.id+'"><strong>'+esc(label)+'</strong><span>'+esc(firstName(rr))+'</span><span>'+esc(rr.status==='checked_in'?'In house':'Arriving')+'</span></button>':'<div class="sc-bed occupied"><strong>'+esc(label)+'</strong><span>'+esc(rr.status==='checked_in'?'In house':'Occupied')+'</span></div>';
    return turnoverUnit(u)};
  let body='';
  if(filtered){
    body='<div class="sc-bed-grid sc-filtered-units">'+visibleUnits.map(unitTile).join('')+'</div>';
  }else if(g.private){
    const u=g.units[0];
    if(fullReservations.length)body='<div class="sc-private">'+fullReservations.map(compactGuest).join('')+'</div>';
    else if(u.housekeeping_status==='dirty')body='<div class="sc-private"><button class="sc-turnover-card sc-hk-action" data-unit="'+u.id+'" data-hk="cleaning"><strong>Vacant · Not ready</strong><span>Needs cleaning · tap to start</span></button></div>';
    else if(u.housekeeping_status==='cleaning')body='<div class="sc-private"><button class="sc-turnover-card cleaning sc-hk-action" data-unit="'+u.id+'" data-hk="clean"><strong>Vacant · Not ready</strong><span>Cleaning · tap when clean</span></button></div>';
    else if(u.housekeeping_status==='maintenance'||u.status!=='available')body='<div class="sc-private"><div class="sc-guest-line"><strong>Unavailable</strong><div class="sc-meta">Maintenance</div></div></div>';
    else body='<div class="sc-private"><div class="sc-guest-line"><strong>Ready</strong><div class="sc-meta">Private room · max '+g.capacity+' guests</div></div></div>';
  }else body='<div class="sc-bed-grid">'+g.units.map(unitTile).join('')+'</div>';
  const occupied=visibleUnits.filter(u=>!!resForUnit(rows,u.id,state.date)).length,ready=visibleUnits.filter(u=>!resForUnit(rows,u.id,state.date)&&u.status==='available'&&u.housekeeping_status==='clean').length,turnover=visibleUnits.filter(u=>['dirty','cleaning'].includes(u.housekeeping_status)).length;
  const stateText=filtered?(visibleUnits.length+' '+(visibleUnits.length===1?'unit':'units')):(g.private?(occupied?'Booked':(ready?'Ready':(turnover?'Cleaning':'Unavailable'))):ready+' ready'+(turnover?' · '+turnover+' cleaning':''));
  const hk=visibleUnits.every(u=>u.housekeeping_status===visibleUnits[0].housekeeping_status)?visibleUnits[0].housekeeping_status:'mixed';
  const footer=filtered?'<footer class="sc-room-footer"><span class="sc-meta">'+esc(state.roomFilter.replace('_',' '))+'</span><strong class="sc-footer-state">'+visibleUnits.length+' matching</strong></footer>':(g.private?'<footer class="sc-room-footer"><span class="sc-meta">Housekeeping</span>'+(StayCorePMS.caps.housekeeping?'<select class="sc-hk-pill" data-units="'+g.units.map(u=>u.id).join(',')+'"><option value="clean" '+(hk==='clean'?'selected':'')+'>Clean</option><option value="dirty" '+(hk==='dirty'?'selected':'')+'>Needs cleaning</option><option value="cleaning" '+(hk==='cleaning'?'selected':'')+'>Cleaning</option><option value="maintenance" '+(hk==='maintenance'?'selected':'')+'>Maintenance</option></select>':'<span class="sc-badge">'+esc(hk)+'</span>')+'</footer>':'<footer class="sc-room-footer"><span class="sc-meta">Housekeeping</span><strong class="sc-footer-state">'+(turnover?turnover+' to clean':'Ready')+'</strong></footer>');
  cards.push('<article class="sc-room-card" data-search="'+esc(hay)+'"><header class="sc-room-head"><div><div class="sc-room-title">'+esc(g.key)+'</div><div class="sc-meta">'+esc(g.type)+(g.private?' · max '+g.capacity:'')+'</div></div><div class="sc-room-count"><strong>'+esc(stateText)+'</strong><span>'+esc(filtered?'Filtered units':(g.private?(occupied?firstName(fullReservations[0]):''):occupied+' occupied'))+'</span></div></header>'+body+footer+'</article>');
}
const filterLabel={all:'All units',arrivals:'Arrivals today',departures:'Departures today',inhouse:'In house',available:'Ready',cleaning:'Cleaning',maintenance:'Maintenance'}[state.roomFilter]||'Units';
el('#sc-view').innerHTML='<section class="sc-toolbar"><div class="sc-list-title"><strong>'+filterLabel+'</strong><span>'+visibleUnitCount+' unit'+(visibleUnitCount===1?'':'s')+'</span></div><div class="sc-datebar"><button class="button" id="sc-prev">‹</button><input id="sc-date" type="date" value="'+state.date+'"><button class="button" id="sc-next">›</button><button class="button sc-today-btn" id="sc-today-date">Today</button></div><input class="sc-search" id="sc-room-search" type="search" placeholder="Search guest, room or bed" value="'+esc(state.search)+'"><div class="sc-segments">'+(StayCorePMS.caps.reservations?[['all','All'],['arrivals','Arrivals'],['departures','Departures'],['inhouse','In house'],['available','Ready'],['cleaning','Cleaning']]:[['all','All'],['cleaning','To clean'],['available','Ready'],['inhouse','Occupied'],['maintenance','Maintenance']]).map(([v,l])=>'<button class="'+(state.roomFilter===v?'active':'')+'" data-filter="'+v+'">'+l+'</button>').join('')+'</div></section><section class="sc-room-list">'+(cards.length?cards.join(''):'<div class="sc-card sc-empty">No matching units.</div>')+(cards.length?'<div class="sc-card sc-empty sc-search-empty" hidden>No matching room, bed or guest.</div>':'')+'</section>';
el('#sc-prev').onclick=()=>{state.date=addDays(state.date,-1);renderRooms()};el('#sc-next').onclick=()=>{state.date=addDays(state.date,1);renderRooms()};el('#sc-today-date').onclick=()=>{state.date=StayCorePMS.today;renderRooms()};el('#sc-date').onchange=e=>{state.date=e.target.value;renderRooms()};
const roomSearch=el('#sc-room-search');roomSearch.oninput=()=>applyCardSearch(roomSearch,'.sc-room-list','.sc-room-card');applyCardSearch(roomSearch,'.sc-room-list','.sc-room-card');
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.roomFilter=b.dataset.filter;renderRooms()});
document.querySelectorAll('.sc-hk-pill').forEach(s=>s.onchange=()=>setHousekeeping(s.dataset.units.split(',').map(Number),s.value).catch(e=>alert(e.message)));
document.querySelectorAll('.sc-hk-action').forEach(b=>b.onclick=()=>setHousekeeping([Number(b.dataset.unit)],b.dataset.hk).catch(e=>alert(e.message)));
bindOpen();
};
const renderAttention=async()=>{const d=state.dashboard||await api('dashboard'),rows=d.alerts||[],labels={payment:'Payment due',overdue:'Checkout overdue',service_recovery:'Guest issue',contact:'Missing phone'},breakdown=d.attention_breakdown||{};
const chips=Object.entries(breakdown).filter(([,n])=>Number(n)>0).map(([k,n])=>'<span class="sc-attention-chip"><strong>'+n+'</strong> '+esc(labels[k]||k)+'</span>').join('');
const cards=rows.map(r=>'<article class="sc-card sc-attention-card"><div class="sc-row"><div><strong>'+esc(r.guest_name||('Booking #'+r.reservation_id))+'</strong><div class="sc-meta">'+esc(r.assignment||'')+(r.check_out?' · checkout '+pretty(r.check_out):'')+'</div></div>'+statusBadge(r)+'</div><div class="sc-attention-issues">'+(r.issues||[]).map(i=>'<div class="sc-attention-issue '+esc(i.type)+'"><span>'+esc(labels[i.type]||i.message)+'</span>'+(i.type==='payment'&&Number(i.balance)>0?'<strong>'+money(i.balance)+'</strong>':'')+'</div>').join('')+'</div><div class="sc-actions"><button class="button button-primary sc-open" data-id="'+r.reservation_id+'">Open booking</button></div></article>').join('');
el('#sc-view').innerHTML='<section class="sc-attention-page"><div class="sc-attention-head"><div><a class="sc-back-link" href="'+esc(StayCorePMS.staff_url||'#')+'">‹ Dashboard</a><h2>Attention</h2><div class="sc-meta">'+rows.length+' booking'+(rows.length===1?'':'s')+' need action</div></div></div><div class="sc-attention-chips">'+chips+'</div><section class="sc-list">'+(cards||'<div class="sc-card sc-empty">Nothing needs attention.</div>')+'</section></section>';
bindOpen();
};

const bookingCard=r=>{const hay=((r.guest_name||'')+' '+(r.phone||'')+' '+(r.email||'')+' '+(r.external_ref||'')+' '+(r.source||'')+' '+assignedNames(r)).toLowerCase();return '<article class="sc-card sc-book-card" data-search="'+esc(hay)+'"><div class="sc-row"><div><button class="sc-link sc-open" data-id="'+r.id+'">'+esc((r.guest_name||'Guest').trim())+'</button><div class="sc-meta">'+esc(assignedNames(r)||'Unassigned')+'</div></div>'+statusBadge(r)+'</div><div class="sc-meta">'+pretty(r.check_in)+' → '+pretty(r.check_out)+' · '+esc(r.source||'direct')+'</div><div class="sc-row" style="margin-top:8px"><div>'+payBadge(r)+'</div><div class="sc-money">'+money(r.total)+'</div></div><div class="sc-actions">'+(r.status==='confirmed'&&StayCorePMS.caps.reservations?'<button class="button sc-status" data-id="'+r.id+'" data-status="checked_in">Check in</button>':'')+checkoutAction(r)+'<button class="button sc-open" data-id="'+r.id+'">Details</button></div></article>'};

const renderBookings=async()=>{const upcoming=state.bookingFilter==='upcoming',from=upcoming?addDays(StayCorePMS.today,1):StayCorePMS.today,to=upcoming?addDays(StayCorePMS.today,90):StayCorePMS.today,rows=await api('reservations?from='+from+'&to='+to);let filtered=rows;if(state.bookingFilter==='arrivals')filtered=rows.filter(r=>day(r.check_in)===StayCorePMS.today&&r.status==='confirmed');if(state.bookingFilter==='departures')filtered=rows.filter(r=>day(r.check_out)===StayCorePMS.today&&r.status==='checked_in');if(state.bookingFilter==='inhouse')filtered=rows.filter(r=>r.status==='checked_in');if(state.bookingFilter==='today')filtered=rows.filter(r=>!['cancelled','no_show'].includes(r.status));const title={today:'Today',arrivals:'Arrivals today',departures:'Departures today',inhouse:'In house',upcoming:'Upcoming'}[state.bookingFilter]||'Bookings';el('#sc-view').innerHTML='<section class="sc-toolbar"><div class="sc-list-title"><strong>'+title+'</strong><span>'+filtered.length+'</span></div><input class="sc-search" id="sc-book-search" type="search" placeholder="Search guest, phone or booking" value="'+esc(state.search)+'"><div class="sc-segments">'+[['today','Today'],['arrivals','Arrivals'],['departures','Departures'],['inhouse','In house'],['upcoming','Upcoming']].map(([v,l])=>'<button class="'+(state.bookingFilter===v?'active':'')+'" data-book-filter="'+v+'">'+l+'</button>').join('')+'</div></section><section class="sc-list">'+(filtered.length?filtered.map(bookingCard).join(''):'<div class="sc-card sc-empty">No bookings in this view.</div>')+(filtered.length?'<div class="sc-card sc-empty sc-search-empty" hidden>No matching booking.</div>':'')+'</section>';const bookSearch=el('#sc-book-search');bookSearch.oninput=()=>applyCardSearch(bookSearch,'.sc-list','.sc-book-card','.sc-list-title span');applyCardSearch(bookSearch,'.sc-list','.sc-book-card','.sc-list-title span');document.querySelectorAll('[data-book-filter]').forEach(b=>b.onclick=()=>{state.bookingFilter=b.dataset.bookFilter;renderBookings()});bindOpen();bindStatus()};

const renderCalendar=async()=>{state.units=await api('units');const from=state.date,to=addDays(from,6),rows=await api('reservations?from='+from+'&to='+to),rooms=groupRooms(state.units),dates=Array.from({length:7},(_,i)=>addDays(from,i));el('#sc-view').innerHTML='<section class="sc-toolbar"><div class="sc-datebar"><button class="button" id="av-prev">‹ 7d</button><input id="av-date" type="date" value="'+from+'"><button class="button" id="av-next">7d ›</button><button class="button sc-today-btn" id="av-today">Today</button></div></section><div class="sc-calendar"><div class="sc-cal-head"><span>Room</span>'+dates.map(d=>'<span>'+new Date(d+'T12:00:00').toLocaleDateString('en-IN',{weekday:'short',day:'numeric'})+'</span>').join('')+'</div>'+rooms.map(g=>'<div class="sc-cal-row"><strong>'+esc(g.key)+'</strong>'+dates.map(d=>{const occ=g.units.filter(u=>resForUnit(rows,u.id,d)).length;return '<span class="'+(occ?'busy':'free')+'">'+(g.private?(occ?'Booked':'Free'):occ+'/'+g.units.length)+'</span>'}).join('')+'</div>').join('')+'</div>';el('#av-prev').onclick=()=>{state.date=addDays(state.date,-7);renderCalendar()};el('#av-next').onclick=()=>{state.date=addDays(state.date,7);renderCalendar()};el('#av-today').onclick=()=>{state.date=StayCorePMS.today;renderCalendar()};el('#av-date').onchange=e=>{state.date=e.target.value;renderCalendar()}};

const renderMore=async()=>{
if(state.more==='activity')return renderActivity();
if(state.more==='inventory')return renderInventory();
if(state.more==='integrations')return renderIntegrations();
const d=state.dashboard||await api('dashboard'),alerts=d.alerts||[];
let html='<section class="sc-more-grid">';
if(StayCorePMS.caps.payments) html+='<article class="sc-card sc-more-card"><h3>Money today</h3><div class="sc-meta">Active stays touching today</div><div class="sc-finance"><div><span class="sc-meta">Expected</span><strong>'+money(d.expected_revenue)+'</strong></div><div><span class="sc-meta">Collected</span><strong>'+money(d.collected)+'</strong></div></div></article>';
html+='<article class="sc-card sc-more-card"><h3>Attention</h3><div class="sc-meta">'+Number(d.attention_count??alerts.length)+' booking'+(Number(d.attention_count??alerts.length)===1?'':'s')+' need action</div><div class="sc-more-links">'+(Number(d.attention_count??alerts.length)?'<button id="sc-open-attention"><span>View attention details</span><span>›</span></button>':'<div class="sc-meta">Nothing urgent.</div>')+'</div></article>';
html+='<article class="sc-card sc-more-card"><h3>Operations</h3><div class="sc-more-links">'+(StayCorePMS.caps.activity?'<button data-more="activity"><span>Activity log</span><span>›</span></button>':'')+'<button data-more="inventory"><span>Rooms & inventory</span><span>›</span></button>'+(StayCorePMS.caps.settings?'<button data-more="integrations"><span>Integrations</span><span>›</span></button>':'')+'</div></article>';
if(StayCorePMS.caps.reports) html+='<article class="sc-card sc-more-card"><h3>Export</h3><div class="sc-meta">Download upcoming stays for reporting or handover.</div><div class="sc-actions"><button class="button" id="sc-export">Export CSV</button></div></article>';
html+='</section>';
el('#sc-view').innerHTML=html;
document.querySelectorAll('[data-more]').forEach(b=>b.onclick=()=>{state.more=b.dataset.more;renderMore()});
const exp=el('#sc-export');if(exp)exp.onclick=exportUpcoming;const attentionBtn=el('#sc-open-attention');if(attentionBtn)attentionBtn.onclick=()=>{if(StayCorePMS.attention_url)window.location.href=StayCorePMS.attention_url;else{state.tab='attention';renderAttention()}};
bindOpen();
};

const moreBack=title=>'<div class="sc-toolbar"><button class="button" id="sc-more-back">‹ More</button><strong style="margin-left:10px">'+esc(title)+'</strong></div>';
const renderActivity=async()=>{const rows=await api('activity?limit=60');el('#sc-view').innerHTML=moreBack('Activity')+'<section class="sc-list">'+(rows.length?rows.map(a=>'<article class="sc-card sc-book-card"><div class="sc-row"><strong>'+esc(a.message)+'</strong><span class="sc-meta">'+pretty(a.created_at)+'</span></div><div class="sc-meta">'+esc(a.user_name||'System')+'</div></article>').join(''):'<div class="sc-card sc-empty">No activity yet.</div>')+'</section>';el('#sc-more-back').onclick=()=>{state.more='home';renderMore()}};
const renderInventory=async()=>{state.units=await api('units');el('#sc-view').innerHTML=moreBack('Rooms & inventory')+'<section class="sc-list">'+state.units.map(u=>'<article class="sc-card sc-book-card"><div class="sc-row"><div><strong>'+esc(u.name)+'</strong><div class="sc-meta">'+esc(u.room_group||u.type)+' · capacity '+u.capacity+'</div></div><span class="sc-badge">'+esc(u.housekeeping_status||'clean')+'</span></div></article>').join('')+'</section>';el('#sc-more-back').onclick=()=>{state.more='home';renderMore()}};
const renderIntegrations=async()=>{const rows=await api('integrations');el('#sc-view').innerHTML=moreBack('Integrations')+'<section class="sc-list">'+Object.values(rows).map(v=>'<article class="sc-card sc-book-card"><div class="sc-row"><div><strong>'+esc(v.label)+'</strong><div class="sc-meta">'+esc((v.capabilities||[]).join(' · '))+'</div></div><span class="sc-badge">'+esc(v.status)+'</span></div></article>').join('')+'</section>';el('#sc-more-back').onclick=()=>{state.more='home';renderMore()}};
const exportUpcoming=async()=>{const rows=await api('reservations?from='+StayCorePMS.today+'&to='+addDays(StayCorePMS.today,90)),q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',lines=[['Booking','Guest','Phone','Units','Check in','Check out','Status','Source','Total','Collected','Balance'].join(',')];rows.forEach(r=>lines.push([r.external_ref||r.id,r.guest_name,r.phone,assignedNames(r),r.check_in,r.check_out,r.status,r.source,r.total,r.payment?.captured,r.payment?.balance].map(q).join(',')));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/csv'}));a.download='staycore-stays.csv';a.click();URL.revokeObjectURL(a.href)};

const readyLabel=u=>{if(u.status!=='available')return 'Unavailable';const h=u.housekeeping_status||'clean';if(h==='clean')return 'Ready';if(h==='dirty')return 'Vacant · not cleaned';if(h==='cleaning')return 'Vacant · cleaning';return 'Maintenance'};
const notReadyUnits=ids=>state.units.filter(u=>ids.map(Number).includes(Number(u.id))&&u.status==='available'&&(u.housekeeping_status||'clean')!=='clean'&&u.housekeeping_status!=='maintenance');
const unitPicker=(selected=[])=>{const groups=groupRooms(state.units);return '<div class="sc-unit-picker">'+groups.map(g=>'<fieldset><legend>'+esc(g.key)+' · '+esc(g.type)+'</legend>'+g.units.map(u=>{const disabled=u.status!=='available'||u.housekeeping_status==='maintenance';return '<label class="sc-unit-option '+esc(u.housekeeping_status||'clean')+'"><input type="checkbox" name="unit_ids" value="'+u.id+'" '+(selected.includes(Number(u.id))?'checked':'')+' '+(disabled?'disabled':'')+'> <span><strong>'+esc(u.name)+'</strong><small>'+esc(readyLabel(u))+(u.type==='room'?' · max '+u.capacity:'')+'</small></span></label>'}).join('')+'</fieldset>').join('')+'</div>'};
const showReadyWarning=(container,units,onConfirm,onChoose)=>{container.innerHTML='<div class="sc-ready-warning"><strong>Vacant, but not ready</strong><p>'+esc(units.map(u=>u.name).join(', '))+' '+(units.length===1?'has':'have')+' not been marked clean. Confirm with housekeeping before assigning.</p><div class="sc-ready-actions"><button type="button" class="button button-primary sc-confirm-clean">Housekeeping confirmed clean · Assign</button><button type="button" class="button sc-choose-other">Choose another</button></div></div>';container.querySelector('.sc-confirm-clean').onclick=async()=>{try{await api('housekeeping',{method:'POST',body:JSON.stringify({unit_ids:units.map(u=>Number(u.id)),status:'clean'})});state.units=await api('units');container.innerHTML='';await onConfirm()}catch(e){alert(e.message)}};container.querySelector('.sc-choose-other').onclick=()=>{container.innerHTML='';if(onChoose)onChoose()}};

const openBooking=async()=>{state.units=await api('units');const d=el('#sc-dialog'),settings=StayCorePMS.settings||{},ci=(settings.check_in_time||'13:00'),co=(settings.check_out_time||'11:00'),today=StayCorePMS.today,tomorrow=addDays(today,1);d.innerHTML='<form class="sc-form" id="sc-book-form"><div class="sc-dialog-head"><div><h2>New booking</h2><div class="sc-meta">Guest details are remembered for future stays.</div></div><button type="button" class="button sc-close">×</button></div><div id="sc-returning-guest"></div><input type="hidden" name="guest_id"><div class="sc-scan-box"><div><strong>Fill from booking screenshot</strong><div class="sc-meta">Upload an OTA / WhatsApp booking screenshot and StayCore will prefill what it can.</div></div><label class="button sc-scan-button">Scan screenshot<input id="sc-booking-scan" type="file" accept="image/*" capture="environment" hidden></label><span class="sc-meta" id="sc-booking-scan-status"></span></div><div class="two"><label>Mobile number<input name="phone" inputmode="tel" autocomplete="tel" placeholder="Search returning guest"></label><label>Email<input name="email" type="email" autocomplete="email" placeholder="Search returning guest"></label></div><div class="two"><label>First name<input name="first_name" required autocomplete="given-name"></label><label>Last name<input name="last_name" autocomplete="family-name"></label></div><details class="sc-guest-more"><summary>Guest profile details</summary><div class="sc-form inline"><div class="two"><label>Nationality<input name="nationality" autocomplete="country-name"></label><label>ID type<select name="id_type"><option value="">Not set</option><option>Passport</option><option>Aadhaar</option><option>Driving Licence</option><option>Other</option></select></label></div><label>ID number<input name="id_number"></label></div></details><div class="sc-auto-box"><div><strong>Automatic room assignment</strong><div class="sc-meta">StayCore fills occupied dorms first before opening another dorm.</div></div><label>Stay type<select name="stay_type"><option value="dorm_any">Dorm · any</option><option value="ac_dorm">AC dorm</option><option value="non_ac_dorm">Non-AC dorm</option><option value="private">Private room</option></select></label><label class="sc-manual-toggle"><input type="checkbox" id="sc-manual-assignment"> Choose room / bed manually</label></div><div id="sc-manual-picker" hidden><label>Room / bed</label>'+unitPicker()+'<div id="sc-book-ready-warning"></div></div><div class="two"><label>Adults<input name="adults" type="number" min="1" value="1"></label><label>Children<input name="children" type="number" min="0" value="0"></label></div><div class="two"><label>Check in<input name="check_in" type="datetime-local" value="'+today+'T'+ci+'" required></label><label>Check out<input name="check_out" type="datetime-local" value="'+tomorrow+'T'+co+'" required></label></div><div class="two"><label>Total ₹<input name="total" type="number" step="0.01"></label><label>Source<select name="source"><option>walkin</option><option>direct</option><option>goibibo</option><option>makemytrip</option><option>booking</option><option>airbnb</option><option>agoda</option><option>other</option></select></label></div><label>Booking reference<input name="external_ref"></label><label>Notes<textarea name="notes"></textarea></label><button class="button button-primary sc-create-booking">Create & assign</button></form>';d.showModal();const form=d.querySelector('form'),returning=form.querySelector('#sc-returning-guest'),manual=form.querySelector('#sc-manual-assignment'),picker=form.querySelector('#sc-manual-picker');d.querySelector('.sc-close').onclick=()=>d.close();manual.onchange=()=>{picker.hidden=!manual.checked};
const bookingScan=form.querySelector('#sc-booking-scan'),bookingScanStatus=form.querySelector('#sc-booking-scan-status');bookingScan.onchange=async()=>{const file=bookingScan.files?.[0];if(!file)return;bookingScanStatus.textContent='Preparing scanner…';try{const text=await scanText(file,bookingScanStatus),found=fillBookingFromText(text,form);bookingScanStatus.textContent=found.length?'Filled '+found.join(', ')+'. Please confirm the details.':'Could not identify fields. You can still enter them manually.';await lookup()}catch(e){bookingScanStatus.textContent=e.message}};

const lookup=async()=>{const phone=form.phone.value.trim(),email=form.email.value.trim();if(phone.replace(/\D/g,'').length<8&&(!email||!email.includes('@'))){returning.innerHTML='';form.guest_id.value='';return}try{const q=[phone?'phone='+encodeURIComponent(phone):'',email?'email='+encodeURIComponent(email):''].filter(Boolean).join('&'),r=await api('guest-lookup?'+q);if(!r.found){returning.innerHTML='';form.guest_id.value='';return}const g=r.guest;form.guest_id.value=g.id||'';for(const key of ['first_name','last_name','phone','email','nationality','id_type','id_number'])if(form.elements[key]&&g[key])form.elements[key].value=g[key];returning.innerHTML='<div class="sc-returning"><strong>Returning guest · '+esc((g.first_name||'')+' '+(g.last_name||''))+'</strong><span>'+Number(g.stay_count||0)+' previous stay'+(Number(g.stay_count||0)===1?'':'s')+' · details loaded</span></div>'}catch(e){returning.innerHTML=''}};
for(const field of [form.phone,form.email])field.addEventListener('input',()=>{clearTimeout(window.__scGuestLookup);window.__scGuestLookup=setTimeout(lookup,350)});

const submit=async(skipReady=false)=>{const fd=new FormData(form),p=Object.fromEntries(fd.entries()),isManual=manual.checked;p.adults=Number(p.adults||1);p.children=Number(p.children||0);p.auto_assign=!isManual;p.unit_ids=isManual?fd.getAll('unit_ids').map(Number):[];if(!isManual)delete p.manual_assignment;const currentStay=String(p.check_in||'').slice(0,10)<=StayCorePMS.today,nr=isManual&&currentStay?notReadyUnits(p.unit_ids):[];if(nr.length&&!skipReady){showReadyWarning(form.querySelector('#sc-book-ready-warning'),nr,()=>submit(true),()=>form.querySelector('.sc-unit-picker').scrollIntoView({behavior:'smooth',block:'center'}));return}const waWin=p.phone?window.open('about:blank','_blank'):null,btn=form.querySelector('.sc-create-booking');btn.disabled=true;btn.textContent='Creating…';try{const created=await api('reservations',{method:'POST',body:JSON.stringify(p)});await refresh();const guest=((created.guest_name||'Guest').trim()),units=assignedNames(created),msg='Hi '+guest+', your booking at Andaz Vibe Stay is confirmed.\n\nStay: '+pretty(created.check_in)+' → '+pretty(created.check_out)+'\n'+(units?'Room/bed: '+units+'\n':'')+'\nComplete your quick self check-in here:\n'+created.self_checkin_url;if(waWin){if(created.phone)routeWhatsApp(created.phone,msg,waWin);else waWin.close()}d.innerHTML='<div class="sc-success"><div class="sc-success-icon">✓</div><h2>Booking created</h2><div class="sc-meta">'+esc(guest)+' · '+esc(units||'Assigned automatically')+'</div><div class="sc-success-actions">'+(created.phone?'<a class="button button-primary sc-wa-success" target="_blank" rel="noopener" href="'+waBusinessUrl(created.phone,msg)+'">Send via WhatsApp Business</a>':'<button class="button" disabled>Add guest phone to send WhatsApp</button>')+'<button class="button sc-copy-success" type="button">Copy check-in link</button><button class="button sc-open-success" type="button">Open booking</button><button class="button sc-done-success" type="button">Done</button></div><div class="sc-meta sc-success-note">Manual send for now · no WhatsApp API call is made.</div></div>';const copy=d.querySelector('.sc-copy-success');if(copy)copy.onclick=async()=>{try{await navigator.clipboard.writeText(created.self_checkin_url);copy.textContent='Copied'}catch(e){window.prompt('Copy self check-in link',created.self_checkin_url)}};d.querySelector('.sc-open-success').onclick=()=>openReservation(created.id);d.querySelector('.sc-done-success').onclick=()=>d.close()}catch(x){if(waWin)waWin.close();btn.disabled=false;btn.textContent='Create & assign';alert(x.message)}};form.onsubmit=e=>{e.preventDefault();submit()}};

const openReservation=async(id,focusPayment=false,forcedBalance=0)=>{
state.units=await api('units');
const r=await api('reservations/'+id),d=el('#sc-dialog'),opts=state.units.map(u=>'<option value="'+u.id+'">'+esc(u.name)+'</option>').join(''),balance=Math.max(Number(r.payment?.balance||0),Number(forcedBalance||0));
const selfBlock=r.status==='checked_out'
?'<div class="sc-self-checkin"><div><strong>Guest checkout feedback</strong><div class="sc-meta">Private Happy / Not happy survey with review and management follow-up</div></div><div class="sc-actions"><button class="button sc-copy-feedback" type="button">Copy link</button>'+(r.phone?'<a class="button" target="_blank" rel="noopener" href="'+waBusinessUrl(r.phone,checkoutMessage(r))+'">Send via WhatsApp Business</a>':'')+'</div></div>'
:'<div class="sc-self-checkin"><div><strong>Guest self check-in</strong><div class="sc-meta">Secure link · country code, ID details and ID image required when missing</div></div><div class="sc-actions"><button class="button sc-copy-checkin" type="button">Copy link</button>'+(r.phone?'<a class="button" target="_blank" rel="noopener" href="'+waBusinessUrl(r.phone,'Complete your self check-in: '+r.self_checkin_url)+'">Send via WhatsApp Business</a>':'')+'</div></div>';
const identity='<section class="sc-detail-section"><h3>Guest identity</h3><div class="sc-id-summary"><div><span class="sc-meta">Nationality</span><strong>'+esc(r.nationality||'Not provided')+'</strong></div><div><span class="sc-meta">ID</span><strong>'+esc(r.id_type||'Not provided')+(r.id_number?' · '+esc(r.id_number):'')+'</strong></div></div>'+(r.has_id_image?'<div class="sc-actions"><button class="button sc-view-id" type="button" data-guest="'+r.guest_id+'">View ID image</button></div><div class="sc-id-preview"></div>':'<div class="sc-meta">No ID image stored yet. Guest self check-in will require one.</div>')+'</section>';
d.innerHTML='<div class="sc-detail"><div class="sc-dialog-head"><div><div class="eyebrow">BOOKING '+esc(r.external_ref||'#'+r.id)+'</div><h2>'+esc((r.guest_name||'Guest').trim())+'</h2><div class="sc-meta">'+esc(assignedNames(r))+'</div></div><button class="button sc-close">×</button></div><div class="sc-detail-summary">'+statusBadge(r)+payBadge(r)+'<strong>'+money(r.total)+'</strong></div><div class="sc-actions">'+(r.phone?'<a class="button" href="tel:'+esc(r.phone)+'">Call</a><a class="button" target="_blank" rel="noopener" href="'+waBusinessUrl(r.phone)+'">WhatsApp Business</a>':'')+(r.status==='confirmed'&&StayCorePMS.caps.reservations?'<button class="button sc-status" data-id="'+r.id+'" data-status="checked_in">Check in</button>':'')+(r.status==='checked_in'&&StayCorePMS.caps.reservations?(balance>0.009?'<button class="button button-primary sc-scroll-payment" type="button">Collect payment to checkout</button>':'<button class="button button-primary sc-status" data-id="'+r.id+'" data-status="checked_out">Check out</button>'):'')+'</div>'+selfBlock+identity+'<form id="sc-edit" class="sc-form inline" style="margin-top:14px"><div class="two"><label>First name<input name="first_name" value="'+esc(r.first_name)+'"></label><label>Last name<input name="last_name" value="'+esc(r.last_name)+'"></label></div><div class="two"><label>Phone<input name="phone" value="'+esc(r.phone)+'"></label><label>Email<input name="email" type="email" value="'+esc(r.email)+'"></label></div><div class="two"><label>Check in<input name="check_in" type="datetime-local" value="'+esc(String(r.check_in).replace(' ','T').slice(0,16))+'"></label><label>Check out<input name="check_out" type="datetime-local" value="'+esc(String(r.check_out).replace(' ','T').slice(0,16))+'"></label></div><div class="two"><label>Total ₹<input name="total" type="number" step="0.01" value="'+r.total+'"></label><label>Source<input name="source" value="'+esc(r.source)+'"></label></div><label>Notes<textarea name="notes">'+esc(r.notes)+'</textarea></label>'+(StayCorePMS.caps.reservations?'<button class="button">Save details</button>':'')+'</form><section class="sc-detail-section"><h3>Room / bed</h3>'+r.assignments.map(a=>'<div class="sc-move-row"><div><strong>'+esc(a.name)+'</strong></div>'+(StayCorePMS.caps.reservations?'<div class="sc-move-controls"><select data-from="'+a.unit_id+'">'+opts+'</select><button class="button sc-move" data-from="'+a.unit_id+'">Move</button></div>':'')+'</div>').join('')+'</section><section id="sc-payment-section" class="sc-detail-section'+(focusPayment?' sc-payment-focus':'')+'"><h3>Payments</h3>'+(balance>0.009?'<div class="sc-payment-due"><strong>Payment required before checkout</strong>Collect '+money(balance)+' to continue.</div>':'')+'<div class="sc-payment-summary">Collected <strong>'+money(r.payment.captured)+'</strong> · Balance <strong>'+money(r.payment.balance)+'</strong></div>'+((r.payments||[]).map(p=>'<div class="sc-payment-row"><span>'+esc(p.method)+' · '+esc(p.status)+'</span><strong>'+money(p.amount)+'</strong></div>').join('')||'<div class="sc-meta">No payments recorded.</div>')+(StayCorePMS.caps.payments?'<form id="sc-payment" class="sc-payment-form"><input name="amount" type="number" step="0.01" min="0.01" placeholder="Amount" value="'+(balance>0.009?balance:'')+'" required><select name="method"><option>cash</option><option>upi</option><option>card</option><option>ota</option><option>bank</option><option>other</option></select><input name="external_ref" placeholder="Reference"><button class="button button-primary">Record</button></form>':'')+'</section></div>';
d.showModal();
const paymentSection=d.querySelector('#sc-payment-section'),scrollPayment=d.querySelector('.sc-scroll-payment');if(scrollPayment)scrollPayment.onclick=()=>paymentSection?.scrollIntoView({behavior:'smooth',block:'start'});if(focusPayment)setTimeout(()=>{paymentSection?.scrollIntoView({behavior:'smooth',block:'start'});const amount=d.querySelector('#sc-payment input[name="amount"]');if(amount)amount.focus({preventScroll:true})},80);
d.querySelector('.sc-close').onclick=()=>d.close();
const copy=d.querySelector('.sc-copy-checkin');if(copy)copy.onclick=async()=>{try{await navigator.clipboard.writeText(r.self_checkin_url);copy.textContent='Copied'}catch(e){window.prompt('Copy self check-in link',r.self_checkin_url)}};
const copyFeedback=d.querySelector('.sc-copy-feedback');if(copyFeedback)copyFeedback.onclick=async()=>{try{await navigator.clipboard.writeText(r.feedback_url);copyFeedback.textContent='Copied'}catch(e){window.prompt('Copy feedback link',r.feedback_url)}};
const viewId=d.querySelector('.sc-view-id');if(viewId)viewId.onclick=async()=>{const preview=d.querySelector('.sc-id-preview');viewId.disabled=true;viewId.textContent='Loading…';try{const img=await api('guests/'+viewId.dataset.guest+'/id-image');const verified=img.verified?'<div class="sc-meta" style="margin-top:8px">Verified camera ID · linked to guest #'+esc(img.guest_id)+(img.source_reservation_id?' · captured for booking #'+esc(img.source_reservation_id):'')+'</div>':'';preview.innerHTML='<img class="sc-id-image" alt="Verified guest ID image" src="data:'+esc(img.mime)+';base64,'+img.data+'">'+verified;viewId.textContent='Hide ID image';viewId.disabled=false;viewId.onclick=()=>{preview.innerHTML='';viewId.textContent='View ID image'}}catch(x){viewId.disabled=false;viewId.textContent='View ID image';alert(x.message)}};
bindStatus();
if(el('#sc-edit'))el('#sc-edit').onsubmit=async e=>{e.preventDefault();try{await api('reservations/'+id,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});d.close();await refresh()}catch(x){alert(x.message)}};
d.querySelectorAll('.sc-move').forEach(b=>b.onclick=async()=>{const row=b.closest('.sc-move-row'),s=b.parentElement.querySelector('select'),to=Number(s.value);if(!to||to===Number(b.dataset.from))return;const target=state.units.find(u=>Number(u.id)===to),currentStay=day(r.check_in)<=StayCorePMS.today;if(currentStay&&target&&target.status==='available'&&(target.housekeeping_status||'clean')!=='clean'){let warn=row.querySelector('.sc-move-warning');if(!warn){warn=document.createElement('div');warn.className='sc-move-warning';row.appendChild(warn)}showReadyWarning(warn,[target],async()=>{await api('reservations/'+id+'/move',{method:'POST',body:JSON.stringify({from_unit_id:Number(b.dataset.from),to_unit_id:to})});await openReservation(id);await loadDashboard()},()=>s.focus());return}try{await api('reservations/'+id+'/move',{method:'POST',body:JSON.stringify({from_unit_id:Number(b.dataset.from),to_unit_id:to})});await openReservation(id);await loadDashboard()}catch(x){alert(x.message)}});
if(el('#sc-payment'))el('#sc-payment').onsubmit=async e=>{e.preventDefault();try{await api('reservations/'+id+'/payments',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});await openReservation(id);await loadDashboard()}catch(x){alert(x.message)}};
};

const activateTab=t=>document.querySelectorAll('.staycore-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));
const render=async()=>{if(state.tab==='attention')return renderAttention();if(state.tab==='rooms')return renderRooms();if(state.tab==='bookings')return renderBookings();if(state.tab==='calendar')return renderCalendar();if(state.tab==='more')return renderMore()};
const refresh=async()=>{await loadDashboard();await render()};
document.addEventListener('DOMContentLoaded',async()=>{activateTab(state.tab);if(el('#sc-new-booking')){if(StayCorePMS.caps.reservations)el('#sc-new-booking').onclick=()=>openBooking().catch(e=>alert(e.message));else el('#sc-new-booking').style.display='none'}document.querySelectorAll('.staycore-tabs button').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.more='home';state.search='';activateTab(state.tab);render()});try{await refresh()}catch(e){el('#sc-view').innerHTML='<div class="sc-card sc-empty">PMS could not load: '+esc(e.message)+'</div>'}});
})();
